%[text] # Simulating elevation profile using Road Grade Profile block
model_name = "HarnessModel_ElevationProfile";
load_system(model_name)
%%
%[text] ## Setup block parameters for Road Grade Profile
RoadSurface.HorizontalDistance = simscape.Value([0 50 100, 150 200 250, 400 490 500], "m");
RoadSurface.GradePercent = [0 0 0, 2 2 2, 0 0 0];
RoadSurface.LeftElevation = simscape.Value(0, "m");

initial.HorizontalPosition = simscape.Value(0, "m");
%[text] Visualize
% Options correspond to the Road Grade Profile block parameters except for
% InterpolationInterval which is unique to this function and used for visualization.
profile_table = buildElevationAndRoadGradeTable( ...
  BaseHorizontalDistance = RoadSurface.HorizontalDistance, ...
  BaseGradePercent = RoadSurface.GradePercent, ...
  InterpolationMethod = "smooth", ...
  InterpolationInterval = simscape.Value(0.1, "m"), ...
  LeftElevation = RoadSurface.LeftElevation );

fig = plotElevationAndRoadGradeProfiles( ... %[output:3ca3b8f9]
  DataSource = "direct", ... %[output:3ca3b8f9]
  BaseHorizontalDistance = RoadSurface.HorizontalDistance, ... %[output:3ca3b8f9]
  BaseGradePercent = RoadSurface.GradePercent, ... %[output:3ca3b8f9]
  RefinedHorizontalDistance = transpose(profile_table.HorizontalDistance), ... %[output:3ca3b8f9]
  RefinedGradePercent = profile_table.GradePercent, ... %[output:3ca3b8f9]
  RefinedElevation = transpose(profile_table.Elevation) ); %[output:3ca3b8f9]

fig.Position(3:4) = [800, 300];  % width, height %[output:3ca3b8f9]
%[text] ## Setup vehicle speed reference
InputLUT.SpeedReference.Time = simscape.Value([0 1 2, 7 29 30, 40 99 100], "s");
InputLUT.SpeedReference.Speed = simscape.Value([0 0 0, 20 20 20, 50 50 50], "km/hr");
%%
sim_in = Simulink.SimulationInput(model_name);
sim_in = setModelParameter(sim_in, StopTime = "60");

applyToModel(sim_in)
%[text] ## Run simulation
sim_out = sim(sim_in);

% The returned table contains signals with the logging names specified in the model.
% Logging names are defined on the signal lines or by Simscape selective logging.
profile_table = bevutil1.SignalUtil.getTimetableFromLoggedSignal(sim_out.logsout);

% Flip the sign for better visualization.
profile_table.("Motor torque") = -profile_table.("Motor torque");
%[text] ## Make plots
%[text] Visually check that the vehicle speed is reasonably following the speed reference.
logical_index = profile_table.Properties.VariableNames == "Speed reference";
unit_text_1 = string(profile_table.Properties.VariableUnits{logical_index});

logical_index = profile_table.Properties.VariableNames == "Vehicle speed";
unit_text_2 = string(profile_table.Properties.VariableUnits{logical_index});

assert(unit_text_1 == unit_text_2)

fig = figure; %[output:13ffdf2d]
fig.Position(3:4) = [800, 300];  % width, height %[output:13ffdf2d]
ax = axes(fig); %[output:13ffdf2d]

bevutil1.SignalUtil.plotTimedData(TimedData=profile_table, SignalName="Speed reference", ... %[output:13ffdf2d]
  ParentAxes=ax, FigureHeight=150); %[output:13ffdf2d]

bevutil1.SignalUtil.plotTimedData(TimedData=profile_table, SignalName="Vehicle speed", ... %[output:13ffdf2d]
  ParentAxes=ax, FigureHeight=150); %[output:13ffdf2d]

title(ax, "Speeds") %[output:13ffdf2d]
ylabel(ax, unit_text_2) %[output:13ffdf2d]
legend(ax, ["Speed reference", "Vehicle speed"], Location="best") %[output:13ffdf2d]
logical_index = profile_table.Properties.VariableNames == "Torque command";
unit_text_1 = string(profile_table.Properties.VariableUnits{logical_index});

logical_index = profile_table.Properties.VariableNames == "Motor torque";
unit_text_2 = string(profile_table.Properties.VariableUnits{logical_index});

assert(unit_text_1 == unit_text_2)

fig = figure; %[output:16cd524c]
fig.Position(3:4) = [800, 300];  % width, height %[output:16cd524c]
ax = axes(fig); %[output:16cd524c]

bevutil1.SignalUtil.plotTimedData(TimedData=profile_table, SignalName="Torque command", ... %[output:16cd524c]
  ParentAxes=ax, FigureHeight=150); %[output:16cd524c]

bevutil1.SignalUtil.plotTimedData(TimedData=profile_table, SignalName="Motor torque", ... %[output:16cd524c]
  ParentAxes=ax, FigureHeight=150); %[output:16cd524c]

title(ax, "Torques") %[output:16cd524c]
ylabel(ax, unit_text_2) %[output:16cd524c]
legend(ax, ["Torque command", "Actual torque"], Location="best") %[output:16cd524c]
%[text] 
% Signal logging names in the model.
% Names are defined on the signal lines or by Simscape selective logging.
varnames = [
"Horizontal position"
"Elevation"
"Road grade"
"Vehicle force"
"G force"
];
for k = 1 : numel(varnames) %[output:group:12b1a0f9]
  bevutil1.SignalUtil.plotTimedData(TimedData=profile_table, SignalName=varnames(k), FigureHeight=150); %[output:697aaa79] %[output:3658a665] %[output:444735e9] %[output:70c78255] %[output:30907a32]
end  % for %[output:group:12b1a0f9]
%[text] 
varnames = [
"Motor current"
"Motor angular speed"
"Motor voltage"
"Battery charge"
"Battery current"
"Battery voltage"
];
for k = 1 : numel(varnames) %[output:group:622d02c5]
  bevutil1.SignalUtil.plotTimedData(TimedData=profile_table, SignalName=varnames(k), FigureHeight=150); %[output:4a55b1ad] %[output:38548bd9] %[output:8ccf80fb] %[output:2b63c6f3] %[output:38ee27e7] %[output:422723aa]
end  % for %[output:group:622d02c5]
%[text] Powers in each component
function vec = get_simscapeValue_vector(tt, name)
logical_index = tt.Properties.VariableNames == name;
unit_text = string(tt.Properties.VariableUnits(logical_index));
vec = simscape.Value(tt.(name), unit_text);
end  % local function

V_vehicle = get_simscapeValue_vector(profile_table, "Vehicle speed");
F_vehicle = get_simscapeValue_vector(profile_table, "Vehicle force");
P_vehicle = convert(V_vehicle .* F_vehicle, "kW");
VehiclePowerTable = timetable(profile_table.Time, P_vehicle, VariableNames="Vehicle power");

w_motor = get_simscapeValue_vector(profile_table, "Motor angular speed");
trq_motor = get_simscapeValue_vector(profile_table, "Motor torque");
P_motor = convert(w_motor .* trq_motor, "kW");
MotorPowerTable = timetable(profile_table.Time, P_motor, VariableNames="Motor power");

i_battery = get_simscapeValue_vector(profile_table, "Battery current");
v_battery = get_simscapeValue_vector(profile_table, "Battery voltage");
P_battery = convert(i_battery .* v_battery, "kW");
BatteryPowerTable = timetable(profile_table.Time, P_battery, VariableNames="Battery power");

bevutil1.SignalUtil.plotTimedData(TimedData=VehiclePowerTable, SignalName="Vehicle power", FigureHeight=150); %[output:6a64144d]
bevutil1.SignalUtil.plotTimedData(TimedData=MotorPowerTable, SignalName="Motor power", FigureHeight=150); %[output:2b9d3f10]
bevutil1.SignalUtil.plotTimedData(TimedData=BatteryPowerTable, SignalName="Battery power", FigureHeight=150); %[output:6ba98585]
